const pptxgen = require('pptxgenjs');

const W = 10;
const H = 5.625;

function addBg(slide, pres, theme) {
  slide.background = { color: theme.bg };
  slide.addShape(pres.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: theme.bg }, line: { color: theme.bg } });
  slide.addShape(pres.ShapeType.rect, { x: 0, y: 0, w: 0.16, h: H, fill: { color: theme.primary }, line: { color: theme.primary } });
}

function addTitle(slide, title, theme, opts = {}) {
  slide.addText(title, {
    x: opts.x ?? 0.48,
    y: opts.y ?? 0.24,
    w: opts.w ?? 8.85,
    h: opts.h ?? 0.62,
    fontFace: theme.fontHead,
    fontSize: opts.fontSize ?? 24,
    bold: true,
    color: opts.color ?? theme.ink,
    margin: 0,
    fit: 'shrink',
    breakLine: false,
  });
}

function addKicker(slide, text, theme, opts = {}) {
  slide.addText(text, {
    x: opts.x ?? 0.5,
    y: opts.y ?? 0.95,
    w: opts.w ?? 8.9,
    h: opts.h ?? 0.25,
    fontFace: theme.fontBody,
    fontSize: opts.fontSize ?? 8.5,
    bold: true,
    color: opts.color ?? theme.muted,
    charSpace: 0.8,
    margin: 0,
    fit: 'shrink',
  });
}

function addFooter(slide, theme, page) {
  slide.addText('JetBrains State of Developer Ecosystem Report 2024', {
    x: 0.5, y: 5.26, w: 5.2, h: 0.16,
    fontFace: theme.fontBody, fontSize: 6.8, color: theme.muted, margin: 0,
  });
  slide.addText(String(page).padStart(2, '0'), {
    x: 9.33, y: 5.12, w: 0.35, h: 0.18,
    fontFace: theme.fontBody, fontSize: 7.5, bold: true, color: theme.muted, align: 'right', margin: 0,
  });
}

function addCard(slide, pres, x, y, w, h, theme, opts = {}) {
  slide.addShape(pres.ShapeType.roundRect, {
    x, y, w, h,
    rectRadius: 0.06,
    fill: { color: opts.fill ?? 'FFFFFF', transparency: opts.transparency ?? 0 },
    line: { color: opts.line ?? theme.border, transparency: opts.lineTransparency ?? 0, width: opts.lineWidth ?? 1 },
    shadow: opts.shadow ? { type: 'outer', color: '000000', opacity: 0.08, blur: 1, angle: 45, distance: 1 } : undefined,
  });
}

function addMetric(slide, pres, x, y, w, h, value, label, theme, opts = {}) {
  addCard(slide, pres, x, y, w, h, theme, { fill: opts.fill ?? 'FFFFFF', line: opts.line ?? theme.border });
  slide.addText(value, { x: x + 0.12, y: y + 0.14, w: w - 0.24, h: h * 0.42, fontFace: theme.fontHead, fontSize: opts.valueSize ?? 22, bold: true, color: opts.color ?? theme.primary, margin: 0, fit: 'shrink' });
  slide.addText(label, { x: x + 0.12, y: y + h * 0.58, w: w - 0.24, h: h * 0.28, fontFace: theme.fontBody, fontSize: opts.labelSize ?? 7.8, color: opts.labelColor ?? theme.ink2, margin: 0, fit: 'shrink' });
}

function addBullets(slide, items, x, y, w, h, theme, opts = {}) {
  const runs = [];
  items.forEach((item, idx) => {
    runs.push({ text: item, options: { bullet: { type: 'ul' }, breakLine: idx < items.length - 1 } });
  });
  slide.addText(runs, {
    x, y, w, h,
    fontFace: theme.fontBody,
    fontSize: opts.fontSize ?? 10.5,
    color: opts.color ?? theme.ink,
    breakLine: false,
    fit: 'shrink',
    margin: opts.margin ?? 0.03,
    paraSpaceAfterPt: opts.paraSpaceAfterPt ?? 8,
    breakLine: false,
  });
}

function pctText(n) { return `${n}%`; }

module.exports = { W, H, addBg, addTitle, addKicker, addFooter, addCard, addMetric, addBullets, pctText };
